export const INTENT_PATTERNS: IntentPattern[] = [
  { intent: "greeting", priority: 10, keywords: [/\b(hello|hi|hey|good morning|good afternoon|good evening|howdy|whats up|sup)\b/i] },
  { intent: "thanks", priority: 10, keywords: [/\b(thanks?|thank you|bye|goodbye|see you|cheers|appreciate)\b/i] },
  { intent: "help", priority: 9, keywords: [/\b(help|what can|how|what do you|assist|support)\b/i] },
  { intent: "pricing", priority: 8, keywords: [/\b(pricing|cost|price|how much|quote|rate|affordable|budget|expensive|cheap|package|plan)\b/i] },
  { intent: "contact", priority: 8, keywords: [/\b(contact|email|phone|reach|get in touch|call|whatsapp|message|reach out)\b/i] },
  { intent: "careers", priority: 8, keywords: [/\b(career|job|jobs|hiring|hire|recruit|vacancy|work with|join|team|apply)\b/i] },
  { intent: "about", priority: 8, keywords: [/\b(about|who|team|founder|cornelius|company|story|background|history|mission)\b/i] },
  { intent: "cybersecurity", priority: 7, keywords: [/\b(cybersecurity|security|penetration|soc|firewall|siem|incident|vulnerability|hack|breach|encrypt|malware|phishing|threat|risk|audit|protect)\b/i] },
  { intent: "web", priority: 7, keywords: [/\b(web\s*(dev|develop|development)|react|next\.?js|node\.?js|typescript|python|full.?stack|website|web app|frontend|backend|api|database|ecommerce)\b/i] },
  { intent: "cloud", priority: 7, keywords: [/\b(cloud|aws|azure|gcp|migration|serverless|docker|kubernetes|infrastructure|hosting|deploy|scale)\b/i] },
  { intent: "devops", priority: 7, keywords: [/\b(devops|ci\/cd|pipeline|terraform|ansible|jenkins|github actions|automation|deploy|release|build)\b/i] },
  { intent: "mobile", priority: 7, keywords: [/\b(mobile|app|react native|flutter|ios|android|smartphone|phone app)\b/i] },
  { intent: "digital", priority: 7, keywords: [/\b(digital|transform|modernize|automation|modern|workflow|process|integration)\b/i] },
  { intent: "compliance", priority: 7, keywords: [/\b(compliance|iso|gdpr|regulation|audit|standard|policy|certif)\b/i] },
  { intent: "ai", priority: 6, keywords: [/\b(ai|artificial intelligence|machine learning|ml|neural|deep learning|nlp|chatbot|automation|intelligent)\b/i] },
  { intent: "security", priority: 6, keywords: [/\b(secure|safety|protect|defend|guard|shield|risk|threat|attack|data protection)\b/i] },
  { intent: "team", priority: 6, keywords: [/\b(team|staff|people|employee|member|engineer|developer|expert|specialist|leader)\b/i] },
];

export function matchIntent(text: string): { intent: string; priority: number } {
  const lower = text.toLowerCase();
  let best = { intent: "fallback", priority: 0 };
  for (const pattern of INTENT_PATTERNS) {
    if (pattern.priority <= best.priority) continue;
    for (const keyword of pattern.keywords) {
      if (keyword.test(lower)) {
        best = { intent: pattern.intent, priority: pattern.priority };
        break;
      }
    }
  }
  return best;
}
